using System;using System.IO;using System.Collections.Generic;using System.Linq;using System.Text;
public static class MixedNativeHostStartupUnit {
 static int passed;static void Check(bool x,string label){if(!x)throw new Exception("UNIT_ASSERTION_FAILED:"+label);passed++;}
 sealed class GatedRead:MemoryStream {public readonly System.Threading.ManualResetEventSlim entered=new System.Threading.ManualResetEventSlim(),release=new System.Threading.ManualResetEventSlim();public override int Read(byte[] b,int o,int n){entered.Set();if(!release.Wait(1000))throw new TimeoutException();return 0;}}
 static MixedNativeHostLaunchPlan Plan(string[] env){return new MixedNativeHostLaunchPlan("D:/fixture/node.exe","D:/fixture/owner.mjs","D:/fixture/context.json",new string('a',64),new string('b',64),new string('c',64),"D:/fixture",env,4096);}
 static void Reject(Action a){bool bad=false;try{a();}catch(InvalidOperationException e){bad=e.Message=="INVALID_MIXED_NATIVE_HOST_STARTUP";}Check(bad,"refusal");}
 public static string Run(){
  var environment=new[]{"SYSTEMROOT=D:/Windows","NODE_OPTIONS=","PATH="};var p=Plan(environment);environment[0]="CHANGED=1";Check(p.CommandLine.Contains("owner.mjs")&&p.CommandLine.EndsWith("\""+new string('a',64)+"\""),"fixed command");Check(p.EnvironmentBlock.Contains("SYSTEMROOT=D:/Windows\0")&&!p.EnvironmentBlock.Contains("CHANGED"),"detached explicit environment");Check(p.EnvironmentBlock.EndsWith("\0\0"),"terminated environment");Check(!p.executionAuthorized&&!p.productionAdmission,"no authority");Reject(()=>Plan(new[]{"PATH=x","path=y"}));Reject(()=>Plan(new[]{"BAD"}));Reject(()=>Plan(new[]{"X=bad\0tail"}));Reject(()=>new MixedNativeHostLaunchPlan("node.exe","D:/fixture/owner.mjs","D:/fixture/context.json",new string('a',64),new string('b',64),new string('c',64),"D:/fixture",new string[0],4096));Reject(()=>new MixedNativeHostLaunchPlan("D:/fixture/node.exe","D:/fixture/owner.mjs","D:/fixture/context.json",new string('a',64),new string('b',64),new string('c',64),"D:/fixture",new string[0],1));
  Reject(()=>new MixedNativeHostLaunchPlan("D:/fixture/node.exe:other.exe","D:/fixture/owner.mjs","D:/fixture/context.json",new string('a',64),new string('b',64),new string('c',64),"D:/fixture",new string[0],4096));
  var closed=new List<long>();var ledger=new MixedNativeHostHandleLedger(h=>{closed.Add(h);return true;});ledger.Keep(MixedNativeHostHandleLedger.Role.RootProcess,10);ledger.Keep(MixedNativeHostHandleLedger.Role.RootThread,11);ledger.Keep(MixedNativeHostHandleLedger.Role.ToHost,12);ledger.ObserveRootCreate(10,11);ledger.CloseAll();Check(closed.SequenceEqual(new long[]{12}),"debug aliases not locally closed");Check(!ledger.Snapshot().allReleased,"aliases pending exit");ledger.DebuggerExitContinued();Check(ledger.Snapshot().allReleased,"OS continued exit releases aliases");ledger.CloseAll();Check(closed.Count==1,"no double close");
  closed=new List<long>();ledger=new MixedNativeHostHandleLedger(h=>{closed.Add(h);return true;});ledger.Keep(MixedNativeHostHandleLedger.Role.RootProcess,20);ledger.Keep(MixedNativeHostHandleLedger.Role.RootThread,21);ledger.ObserveRootCreate(30,31);Check(closed.OrderBy(x=>x).SequenceEqual(new long[]{20,21})&&!ledger.Snapshot().allReleased,"different root handles closed once");ledger.DebuggerExitContinued();Check(ledger.Snapshot().allReleased,"borrowed debugger root observed exited");
  closed=new List<long>();ledger=new MixedNativeHostHandleLedger(h=>{closed.Add(h);return true;});ledger.Keep(MixedNativeHostHandleLedger.Role.RootProcess,40);ledger.Keep(MixedNativeHostHandleLedger.Role.RootThread,41);ledger.ObserveRootCreate(40,41);Check(ledger.BorrowRootForAbort()==40,"DUP_FAILURE_ALIAS_BORROW_FOR_ABORT");ledger.DebuggerExitContinued();ledger.CloseAll();Check(closed.Count==0&&ledger.BorrowRootForAbort()==0,"DUP_FAILURE_ALIAS_NO_SECOND_CLOSE");
  int attempts=0;ledger=new MixedNativeHostHandleLedger(h=>{attempts++;return false;});ledger.Keep(MixedNativeHostHandleLedger.Role.ToHost,22);ledger.CloseAll();ledger.CloseAll();Check(attempts==1&&!ledger.Snapshot().allReleased&&ledger.Snapshot().failed,"uncertain close no retry");
  ledger=new MixedNativeHostHandleLedger(h=>true);ledger.Keep(MixedNativeHostHandleLedger.Role.ToHost,1);Reject(()=>ledger.Keep(MixedNativeHostHandleLedger.Role.FromHost,1));Check(ledger.Snapshot().failed,"duplicate ownership unknown");
  var d=new MixedNativeHostDiagnostics(new MemoryStream(),8,4);d.Start();Check(d.Wait(1000)&&d.Snapshot().emptyComplete&&d.Snapshot().bytes==0,"empty diagnostics");d.Stop();Check(d.Wait(1000)&&d.Snapshot().workersComplete,"diagnostic stop observed");
  d=new MixedNativeHostDiagnostics(new MemoryStream(Encoding.UTF8.GetBytes("problem")),16,3);d.Start();Check(d.Wait(1000)&&!d.Snapshot().emptyComplete&&d.Snapshot().bytes==7&&d.Snapshot().sha256!=null,"nonempty stderr not success");d.Stop();Check(d.Wait(1000),"nonempty worker closed");
  d=new MixedNativeHostDiagnostics(new MemoryStream(new byte[10]),3,8);d.Start();Check(d.Wait(1000)&&d.Snapshot().failed&&d.Snapshot().bytes==4&&d.Snapshot().sha256==null,"overflow max+1 no digest fallback");d.Stop();Check(d.Wait(1000),"overflow close observed");
  var gated=new GatedRead();d=new MixedNativeHostDiagnostics(gated,8,4);try{d.Start();Check(gated.entered.Wait(1000),"diagnostic read entered");d.Stop();}finally{gated.release.Set();Check(d.Wait(1000),"stopped diagnostic observed");}Check(d.Snapshot().workersComplete&&d.Snapshot().bytes==0&&!d.Snapshot().eof&&!d.Snapshot().emptyComplete,"STOPPED_ZERO_BYTES_IS_NOT_EOF");
  return "{\"kind\":\"PURE_HOST_STARTUP_UNIT\",\"passed\":"+passed+",\"actualWindowsCalls\":0,\"actualCollectorRuns\":0}";
 }
}
